static int[] zArray(String s) {
    int n = s.length();
    int[] z = new int[n];
    int l = 0, r = 0;
    for (int i = 1; i < n; i++) {
        if (i < r) z[i] = Math.min(r - i, z[i - l]);
        while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;
        if (i + z[i] > r) {
            l = i;
            r = i + z[i];
        }
    }
    if (n > 0) z[0] = n;
    return z;
}

static int longestPrefixIn(String word, String text) {
    int[] z = zArray(word + "#" + text);
    int best = 0;
    for (int i = word.length() + 1; i < z.length; i++) best = Math.max(best, z[i]);
    return best;
}

