void zArray(const char* s, int n, int* z) {
    for (int i = 0; i < n; i++) z[i] = 0;
    int l = 0, r = 0;
    for (int i = 1; i < n; i++) {
        if (i < r) z[i] = (r - i < z[i - l]) ? r - i : z[i - l];
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] > r) {
            l = i;
            r = i + z[i];
        }
    }
    if (n > 0) z[0] = n;
}

int longestPrefixIn(const char* word, const char* text) {
    int w = strlen(word), t = strlen(text), n = w + 1 + t;
    char* s = malloc(n + 1);
    int* z = malloc(n * sizeof(int));
    memcpy(s, word, w);
    s[w] = '#';
    memcpy(s + w + 1, text, t + 1);
    zArray(s, n, z);
    int best = 0;
    for (int i = w + 1; i < n; i++) if (z[i] > best) best = z[i];
    free(s);
    free(z);
    return best;
}

