def prefix_function(s):
    pi = [0] * len(s)
    for i in range(1, len(s)):
        k = pi[i - 1]
        while k > 0 and s[i] != s[k]:
            k = pi[k - 1]
        if s[i] == s[k]:
            k += 1
        pi[i] = k
    return pi


def borders(s):
    pi = prefix_function(s)
    out = []
    k = pi[-1] if s else 0
    while k > 0:
        out.append(k)
        k = pi[k - 1]
