    int[] pi = prefixFunction(s);
    List<Integer> out = new ArrayList<>();
    int k = s.isEmpty() ? 0 : pi[s.length() - 1];
    while (k > 0) {
        out.add(k);
        k = pi[k - 1];
    }
    return out;
}

