void prefixFunction(const char* s, int n, int* pi) {
    if (n > 0) pi[0] = 0;
    for (int i = 1; i < n; i++) {
        int k = pi[i - 1];
        while (k > 0 && s[i] != s[k]) k = pi[k - 1];
        if (s[i] == s[k]) k++;
        pi[i] = k;
    }
}

int borders(const char* s, int* out) {
    int n = strlen(s), m = 0;
    int* pi = malloc((n > 0 ? n : 1) * sizeof(int));
    prefixFunction(s, n, pi);
    int k = n > 0 ? pi[n - 1] : 0;
    while (k > 0) {
        out[m++] = k;
        k = pi[k - 1];
    }
    free(pi);
    return m;
}
